    42	function useOptions({isGroupChat}: NewChatPageProps) {
    43	    const [searchTerm, debouncedSearchTerm, setSearchTerm] = useDebouncedState('');
    44	    const [selectedOptions, setSelectedOptions] = useState<Array<ListItem & OptionData>>([]);
    45	    const [betas] = useOnyx(ONYXKEYS.BETAS);
    46	    const [newGroupDraft] = useOnyx(ONYXKEYS.NEW_GROUP_CHAT_DRAFT);
    47	    const personalData = useCurrentUserPersonalDetails();
    48	    const {didScreenTransitionEnd} = useScreenWrapperTranstionStatus();
    49	    const {options: listOptions, areOptionsInitialized} = useOptionsList({
    50	        shouldInitialize: didScreenTransitionEnd,
    51	    });
    52	
    53	    const defaultOptions = useMemo(() => {
    54	        const filteredOptions = OptionsListUtils.getFilteredOptions(
    55	            listOptions.reports ?? [],
    56	            listOptions.personalDetails ?? [],
    57	            betas ?? [],
    58	            '',
    59	            selectedOptions,
    60	            isGroupChat ? excludedGroupEmails : [],
    61	            false,
    62	            true,
    63	            false,
    64	            {},
    65	            [],
    66	            false,
    67	            {},
    68	            [],
    69	            true,
    70	            undefined,
    71	            undefined,
    72	            0,
    73	            undefined,
    74	            true,
    75	        );
    76	        return filteredOptions;
    77	    }, [betas, isGroupChat, listOptions.personalDetails, listOptions.reports, selectedOptions]);
    78	
    79	    const options = useMemo(() => {
    80	        const filteredOptions = OptionsListUtils.filterOptions(defaultOptions, debouncedSearchTerm, {
    81	            selectedOptions,
    82	            excludeLogins: isGroupChat ? excludedGroupEmails : [],
    83	            maxRecentReportsToShow: CONST.IOU.MAX_RECENT_REPORTS_TO_SHOW,
    84	        });
    85	
    86	        return filteredOptions;
    87	    }, [debouncedSearchTerm, defaultOptions, isGroupChat, selectedOptions]);
    88	    const cleanSearchTerm = useMemo(() => debouncedSearchTerm.trim().toLowerCase(), [debouncedSearchTerm]);
    89	    const headerMessage = useMemo(() => {
    90	        return OptionsListUtils.getHeaderMessage(
    91	            options.personalDetails.length + options.recentReports.length !== 0,
    92	            !!options.userToInvite,
    93	            debouncedSearchTerm.trim(),
    94	            selectedOptions.some((participant) => OptionsListUtils.getPersonalDetailSearchTerms(participant).join(' ').toLowerCase?.().includes(cleanSearchTerm)),
    95	        );
    96	    }, [cleanSearchTerm, debouncedSearchTerm, options.personalDetails.length, options.recentReports.length, options.userToInvite, selectedOptions]);
    97	
    98	    useEffect(() => {
    99	        if (!debouncedSearchTerm.length) {
   100	            return;
   101	        }
   102	
   103	        Report.searchInServer(debouncedSearchTerm);
   104	    }, [debouncedSearchTerm]);
   105	
   106	    useEffect(() => {
   107	        if (!newGroupDraft?.participants) {
   108	            return;
   109	        }
   110	        const newSelectedOptions: OptionData[] = [];
   111	        newGroupDraft.participants.forEach((participant) => {
   112	            if (participant.accountID === personalData.accountID) {
   113	                return;
   114	            }
   115	            let participantOption: OptionData | undefined | null = listOptions.personalDetails.find((option) => option.accountID === participant.accountID);
   116	            if (!participantOption) {
   117	                participantOption = OptionsListUtils.getUserToInviteOption({
   118	                    searchValue: participant.login,
   119	                });
   120	            }
   121	            if (!participantOption) {
   122	                return;
   123	            }
   124	            newSelectedOptions.push({
   125	                ...participantOption,
   126	                isSelected: true,
   127	            });
   128	        });
   129	        setSelectedOptions(newSelectedOptions);
   130	    }, [newGroupDraft?.participants, listOptions.personalDetails, personalData.accountID]);
   131	
   132	    return {
   133	        ...options,
   134	        searchTerm,
   135	        debouncedSearchTerm,
   136	        setSearchTerm,
   137	        areOptionsInitialized: areOptionsInitialized && didScreenTransitionEnd,
   138	        selectedOptions,
   139	        setSelectedOptions,
   140	        headerMessage,
   141	    };
   142	}
