   144	function NewChatPage({isGroupChat}: NewChatPageProps) {
   145	    const {translate} = useLocalize();
   146	    const {isOffline} = useNetwork();
   147	    // We need to use isSmallScreenWidth instead of shouldUseNarrowLayout to show offline indicator on small screen only
   148	    const {isSmallScreenWidth} = useResponsiveLayout();
   149	    const styles = useThemeStyles();
   150	    const personalData = useCurrentUserPersonalDetails();
   151	    const {insets} = useStyledSafeAreaInsets();
   152	    const [isSearchingForReports] = useOnyx(ONYXKEYS.IS_SEARCHING_FOR_REPORTS, {initWithStoredValues: false});
   153	    const selectionListRef = useRef<SelectionListHandle>(null);
   154	
   155	    const {headerMessage, searchTerm, debouncedSearchTerm, setSearchTerm, selectedOptions, setSelectedOptions, recentReports, personalDetails, userToInvite, areOptionsInitialized} =
   156	        useOptions({
   157	            isGroupChat,
   158	        });
   159	
   160	    const [sections, firstKeyForList] = useMemo(() => {
   161	        const sectionsList: OptionsListUtils.CategorySection[] = [];
   162	        let firstKey = '';
   163	
   164	        const formatResults = OptionsListUtils.formatSectionsFromSearchTerm(debouncedSearchTerm, selectedOptions, recentReports, personalDetails);
   165	        sectionsList.push(formatResults.section);
   166	
   167	        if (!firstKey) {
   168	            firstKey = OptionsListUtils.getFirstKeyForList(formatResults.section.data);
   169	        }
   170	
   171	        sectionsList.push({
   172	            title: translate('common.recents'),
   173	            data: recentReports,
   174	            shouldShow: !isEmpty(recentReports),
   175	        });
   176	        if (!firstKey) {
   177	            firstKey = OptionsListUtils.getFirstKeyForList(recentReports);
   178	        }
   179	
   180	        sectionsList.push({
   181	            title: translate('common.contacts'),
   182	            data: personalDetails,
   183	            shouldShow: !isEmpty(personalDetails),
   184	        });
   185	        if (!firstKey) {
   186	            firstKey = OptionsListUtils.getFirstKeyForList(personalDetails);
   187	        }
   188	
   189	        if (userToInvite) {
   190	            sectionsList.push({
   191	                title: undefined,
   192	                data: [userToInvite],
   193	                shouldShow: true,
   194	            });
   195	            if (!firstKey) {
   196	                firstKey = OptionsListUtils.getFirstKeyForList([userToInvite]);
   197	            }
   198	        }
   199	
   200	        return [sectionsList, firstKey];
   201	    }, [debouncedSearchTerm, selectedOptions, recentReports, personalDetails, translate, userToInvite]);
   202	
   203	    /**
   204	     * Creates a new 1:1 chat with the option and the current user,
   205	     * or navigates to the existing chat if one with those participants already exists.
   206	     */
   207	    const createChat = useCallback(
   208	        (option?: OptionsListUtils.Option) => {
   209	            if (option?.isSelfDM) {
   210	                Navigation.dismissModal(option.reportID);
   211	                return;
   212	            }
   213	            let login = '';
   214	
   215	            if (option?.login) {
   216	                login = option.login;
   217	            } else if (selectedOptions.length === 1) {
   218	                login = selectedOptions[0].login ?? '';
   219	            }
   220	            if (!login) {
   221	                Log.warn('Tried to create chat with empty login');
   222	                return;
   223	            }
   224	            Report.navigateToAndOpenReport([login]);
   225	        },
   226	        [selectedOptions],
   227	    );
   228	
   229	    const itemRightSideComponent = useCallback(
   230	        (item: ListItem & OptionsListUtils.Option, isFocused?: boolean) => {
   231	            if (!!item.isSelfDM || (item.accountID && CONST.NON_ADDABLE_ACCOUNT_IDS.includes(item.accountID))) {
   232	                return null;
   233	            }
   234	            /**
   235	             * Removes a selected option from list if already selected. If not already selected add this option to the list.
   236	             * @param  option
   237	             */
   238	            function toggleOption(option: ListItem & Partial<OptionData>) {
   239	                const isOptionInList = !!option.isSelected;
   240	
   241	                let newSelectedOptions;
   242	
   243	                if (isOptionInList) {
   244	                    newSelectedOptions = reject(selectedOptions, (selectedOption) => selectedOption.login === option.login);
   245	                } else {
   246	                    newSelectedOptions = [...selectedOptions, {...option, isSelected: true, selected: true, reportID: option.reportID ?? '-1'}];
   247	                }
   248	
   249	                selectionListRef?.current?.clearInputAfterSelect?.();
   250	
   251	                setSelectedOptions(newSelectedOptions);
   252	            }
   253	
   254	            if (item.isSelected) {
   255	                return (
   256	                    <PressableWithFeedback
   257	                        onPress={() => toggleOption(item)}
   258	                        disabled={item.isDisabled}
   259	                        role={CONST.ROLE.BUTTON}
   260	                        accessibilityLabel={CONST.ROLE.BUTTON}
   261	                        style={[styles.flexRow, styles.alignItemsCenter, styles.ml3]}
   262	                    >
   263	                        <SelectCircle isChecked={item.isSelected} />
   264	                    </PressableWithFeedback>
   265	                );
   266	            }
   267	            const buttonInnerStyles = isFocused ? styles.buttonDefaultHovered : {};
   268	            return (
   269	                <Button
   270	                    onPress={() => toggleOption(item)}
   271	                    style={[styles.pl2]}
   272	                    text={translate('newChatPage.addToGroup')}
   273	                    innerStyles={buttonInnerStyles}
   274	                    small
   275	                />
   276	            );
   277	        },
   278	        [selectedOptions, setSelectedOptions, styles, translate],
   279	    );
   280	
   281	    const createGroup = useCallback(() => {
   282	        if (!personalData || !personalData.login || !personalData.accountID) {
   283	            return;
   284	        }
   285	        const selectedParticipants: SelectedParticipant[] = selectedOptions.map((option: OptionData) => ({login: option.login ?? '', accountID: option.accountID ?? -1}));
   286	        const logins = [...selectedParticipants, {login: personalData.login, accountID: personalData.accountID}];
   287	        Report.setGroupDraft({participants: logins});
   288	        Navigation.navigate(ROUTES.NEW_CHAT_CONFIRM);
   289	    }, [selectedOptions, personalData]);
   290	
   291	    const footerContent = useMemo(
   292	        () => (
   293	            <>
   294	                <ReferralProgramCTA
   295	                    referralContentType={CONST.REFERRAL_PROGRAM.CONTENT_TYPES.START_CHAT}
   296	                    style={selectedOptions.length ? styles.mb5 : undefined}
   297	                />
   298	
   299	                {!!selectedOptions.length && (
   300	                    <Button
   301	                        success
   302	                        large
   303	                        text={translate('common.next')}
   304	                        onPress={createGroup}
   305	                        pressOnEnter
   306	                    />
   307	                )}
   308	            </>
   309	        ),
   310	        [createGroup, selectedOptions.length, styles.mb5, translate],
   311	    );
   312	
   313	    return (
   314	        <ScreenWrapper
   315	            shouldEnableKeyboardAvoidingView={false}
   316	            includeSafeAreaPaddingBottom={isOffline}
   317	            shouldShowOfflineIndicator={false}
   318	            includePaddingTop={false}
   319	            shouldEnablePickerAvoiding={false}
   320	            testID={NewChatPage.displayName}
   321	            // Disable the focus trap of this page to activate the parent focus trap in `NewChatSelectorPage`.
   322	            focusTrapSettings={{active: false}}
   323	        >
   324	            <KeyboardAvoidingView
   325	                style={styles.flex1}
   326	                behavior="padding"
   327	                // Offset is needed as KeyboardAvoidingView in nested inside of TabNavigator instead of wrapping whole screen.
   328	                // This is because when wrapping whole screen the screen was freezing when changing Tabs.
   329	                keyboardVerticalOffset={variables.contentHeaderHeight + (insets?.top ?? 0) + variables.tabSelectorButtonHeight + variables.tabSelectorButtonPadding}
   330	            >
   331	                <SelectionList<OptionsListUtils.Option & ListItem>
   332	                    ref={selectionListRef}
   333	                    ListItem={UserListItem}
   334	                    sections={areOptionsInitialized ? sections : CONST.EMPTY_ARRAY}
   335	                    textInputValue={searchTerm}
   336	                    textInputHint={isOffline ? `${translate('common.youAppearToBeOffline')} ${translate('search.resultsAreLimited')}` : ''}
   337	                    onChangeText={setSearchTerm}
   338	                    textInputLabel={translate('selectionList.nameEmailOrPhoneNumber')}
   339	                    headerMessage={headerMessage}
   340	                    onSelectRow={createChat}
   341	                    shouldSingleExecuteRowSelect
   342	                    onConfirm={(e, option) => (selectedOptions.length > 0 ? createGroup() : createChat(option))}
   343	                    rightHandSideComponent={itemRightSideComponent}
   344	                    footerContent={footerContent}
   345	                    showLoadingPlaceholder={!areOptionsInitialized}
   346	                    shouldPreventDefaultFocusOnSelectRow={!DeviceCapabilities.canUseTouchScreen()}
   347	                    isLoadingNewOptions={!!isSearchingForReports}
   348	                    initiallyFocusedOptionKey={firstKeyForList}
   349	                    shouldTextInputInterceptSwipe
   350	                />
   351	                {isSmallScreenWidth && <OfflineIndicator />}
   352	            </KeyboardAvoidingView>
   353	        </ScreenWrapper>
   354	    );
   355	}
