    10	import SafeAreaConsumer from '@components/SafeAreaConsumer';
    11	import type {SafeAreaChildrenProps} from '@components/SafeAreaConsumer/types';
    12	import ScrollView from '@components/ScrollView';
    13	import ScrollViewWithContext from '@components/ScrollViewWithContext';
    14	import useThemeStyles from '@hooks/useThemeStyles';
    15	import * as ErrorUtils from '@libs/ErrorUtils';
    16	import type {Form} from '@src/types/form';
    17	import type ChildrenProps from '@src/types/utils/ChildrenProps';
    18	import {isEmptyObject} from '@src/types/utils/EmptyObject';
    19	import type {FormInputErrors, FormProps, InputRefs} from './types';
    20	
    21	type FormWrapperOnyxProps = {
    22	    /** Contains the form state that must be accessed outside the component */
    23	    formState: OnyxEntry<Form>;
    24	};
    25	
    26	type FormWrapperProps = ChildrenProps &
    27	    FormWrapperOnyxProps &
    28	    FormProps & {
    29	        /** Submit button styles */
    30	        submitButtonStyles?: StyleProp<ViewStyle>;
    31	
    32	        /** Whether to apply flex to the submit button */
    33	        submitFlexEnabled?: boolean;
    34	
    35	        /** Server side errors keyed by microtime */
    36	        errors: FormInputErrors;
    37	
    38	        /** Assuming refs are React refs */
    39	        inputRefs: RefObject<InputRefs>;
    40	
    41	        /** Whether the submit button is disabled */
    42	        isSubmitDisabled?: boolean;
    43	
    44	        /** Callback to submit the form */
    45	        onSubmit: () => void;
    46	    };
    47	
    48	function FormWrapper({
    49	    onSubmit,
    50	    children,
    51	    formState,
    52	    errors,
    53	    inputRefs,
    54	    submitButtonText,
    55	    footerContent,
    56	    isSubmitButtonVisible = true,
    57	    style,
    58	    submitButtonStyles,
    59	    submitFlexEnabled = true,
    60	    enabledWhenOffline,
    61	    isSubmitActionDangerous = false,
    62	    formID,
    63	    shouldUseScrollView = true,
    64	    scrollContextEnabled = false,
    65	    shouldHideFixErrorsAlert = false,
    66	    disablePressOnEnter = false,
    67	    isSubmitDisabled = false,
    68	}: FormWrapperProps) {
    69	    const styles = useThemeStyles();
    70	    const formRef = useRef<RNScrollView>(null);
    71	    const formContentRef = useRef<View>(null);
    72	    const errorMessage = useMemo(() => (formState ? ErrorUtils.getLatestErrorMessage(formState) : undefined), [formState]);
    73	
    74	    const onFixTheErrorsLinkPressed = useCallback(() => {
    75	        const errorFields = !isEmptyObject(errors) ? errors : formState?.errorFields ?? {};
    76	        const focusKey = Object.keys(inputRefs.current ?? {}).find((key) => Object.keys(errorFields).includes(key));
    77	
    78	        if (!focusKey) {
    79	            return;
    80	        }
    81	
    82	        const focusInput = inputRefs.current?.[focusKey]?.current;
    83	
    84	        // Dismiss the keyboard for non-text fields by checking if the component has the isFocused method, as only TextInput has this method.
    85	        if (typeof focusInput?.isFocused !== 'function') {
    86	            Keyboard.dismiss();
    87	        }
