    94	                formRef.current?.scrollTo({
    95	                    y: y - 10,
    96	                    animated: false,
    97	                }),
    98	            );
    99	        }
   100	
   101	        // Focus the input after scrolling, as on the Web it gives a slightly better visual result
   102	        focusInput?.focus?.();
   103	    }, [errors, formState?.errorFields, inputRefs]);
   104	
   105	    const scrollViewContent = useCallback(
   106	        (safeAreaPaddingBottomStyle: SafeAreaChildrenProps['safeAreaPaddingBottomStyle']) => (
   107	            <FormElement
   108	                key={formID}
   109	                ref={formContentRef}
   110	                style={[style, safeAreaPaddingBottomStyle.paddingBottom ? safeAreaPaddingBottomStyle : styles.pb5]}
   111	            >
   112	                {children}
   113	                {isSubmitButtonVisible && (
   114	                    <FormAlertWithSubmitButton
   115	                        buttonText={submitButtonText}
   116	                        isDisabled={isSubmitDisabled}
   117	                        isAlertVisible={((!isEmptyObject(errors) || !isEmptyObject(formState?.errorFields)) && !shouldHideFixErrorsAlert) || !!errorMessage}
   118	                        isLoading={!!formState?.isLoading}
   119	                        message={isEmptyObject(formState?.errorFields) ? errorMessage : undefined}
   120	                        onSubmit={onSubmit}
   121	                        footerContent={footerContent}
   122	                        onFixTheErrorsLinkPressed={onFixTheErrorsLinkPressed}
   123	                        containerStyles={[styles.mh0, styles.mt5, submitFlexEnabled ? styles.flex1 : {}, submitButtonStyles]}
   124	                        enabledWhenOffline={enabledWhenOffline}
   125	                        isSubmitActionDangerous={isSubmitActionDangerous}
   126	                        disablePressOnEnter={disablePressOnEnter}
   127	                        enterKeyEventListenerPriority={1}
   128	                    />
   129	                )}
   130	            </FormElement>
   131	        ),
   132	        [
   133	            formID,
   134	            style,
   135	            styles.pb5,
   136	            styles.mh0,
   137	            styles.mt5,
   138	            styles.flex1,
   139	            children,
   140	            isSubmitButtonVisible,
   141	            submitButtonText,
   142	            isSubmitDisabled,
   143	            errors,
   144	            formState?.errorFields,
   145	            formState?.isLoading,
   146	            shouldHideFixErrorsAlert,
   147	            errorMessage,
   148	            onSubmit,
   149	            footerContent,
   150	            onFixTheErrorsLinkPressed,
   151	            submitFlexEnabled,
   152	            submitButtonStyles,
   153	            enabledWhenOffline,
   154	            isSubmitActionDangerous,
   155	            disablePressOnEnter,
   156	        ],
   157	    );
   158	
   159	    if (!shouldUseScrollView) {
   160	        return scrollViewContent({});
   161	    }
   162	
   163	    return (
   164	        <SafeAreaConsumer>
   165	            {({safeAreaPaddingBottomStyle}) =>
   166	                scrollContextEnabled ? (
   167	                    <ScrollViewWithContext
   168	                        style={[styles.w100, styles.flex1]}
   169	                        contentContainerStyle={styles.flexGrow1}
   170	                        keyboardShouldPersistTaps="handled"
   171	                        ref={formRef}
   172	                    >
   173	                        {scrollViewContent(safeAreaPaddingBottomStyle)}
   174	                    </ScrollViewWithContext>
   175	                ) : (
   176	                    <ScrollView
   177	                        style={[styles.w100, styles.flex1]}
   178	                        contentContainerStyle={styles.flexGrow1}
   179	                        keyboardShouldPersistTaps="handled"
   180	                        ref={formRef}
   181	                    >
   182	                        {scrollViewContent(safeAreaPaddingBottomStyle)}
   183	                    </ScrollView>
   184	                )
   185	            }
   186	        </SafeAreaConsumer>
   187	    );
   188	}
   189	
   190	FormWrapper.displayName = 'FormWrapper';
   191	
   192	export default withOnyx<FormWrapperProps, FormWrapperOnyxProps>({
   193	    formState: {
   194	        // withOnyx typings are not able to handle such generic cases like this one, since it's a generic component we need to cast the keys to any
   195	        // eslint-disable-next-line @typescript-eslint/no-unsafe-return, @typescript-eslint/no-explicit-any
   196	        key: (props) => props.formID as any,
   197	    },
   198	})(FormWrapper);
